"""Native-format contract tests; generated bytes are not gameplay evidence."""
from dataclasses import replace
import os
from pathlib import Path
import random
import tempfile
import unittest
from unittest.mock import patch

from koei_editor.games.dw3.models import SaveError
from koei_editor.games.dw8xl_vita import parser
from koei_editor.shared.adapter_contract import BoundScalarAdapter
from tests.scalar_contract import ScalarContractTests


def procedural_raw():
    payload = bytearray(random.Random(8173).randbytes(parser.PAYLOAD_SIZE))
    payload[:5] = parser.SIGNATURE
    for field in parser.BASE_FIELDS:
        value = 25 if '_compatibility_' in field.id else 500
        payload[field.offset:field.offset + field.size] = value.to_bytes(field.size, 'little')
    for index in range(parser.WEAPON_COUNT):
        base = parser.WEAPON_BASE + index * parser.WEAPON_STRIDE
        payload[base] = 0
        payload[base + 2:base + 4] = b'\xff\xff'
    base = parser.WEAPON_BASE
    payload[base] = 1
    payload[base + 2:base + 4] = (17).to_bytes(2, 'little')
    payload[base + 6:base + 12] = bytes((0, 1, 2, 3, 4, 250))
    payload[base + 12:base + 18] = bytes((3, 0, 11, 5, 7, 4))
    return bytes(payload) + bytes((sum(payload) & 255,))


class VitaRegisteredContractTests(ScalarContractTests, unittest.TestCase):
    game_id = parser.GAME_ID

    def fixture_bytes(self):
        return procedural_raw()


class VitaGuiTests(unittest.TestCase):
    def test_open_stage_undo_review_theme_save_and_restore(self):
        import tkinter as tk
        from koei_editor.games.dw8xl_vita.editor import Editor
        try:
            root = tk.Tk()
        except tk.TclError as error:
            self.skipTest(f'Tk display unavailable: {error}')
        root.withdraw()
        try:
            with tempfile.TemporaryDirectory() as temporary:
                folder = Path(temporary)
                original = procedural_raw()
                source = folder / 'MainData00.dat'
                source.write_bytes(original)
                editor = Editor(root)
                with patch('koei_editor.shared.verified_gui.filedialog.askopenfilename', return_value=str(source)), \
                        patch('koei_editor.shared.verified_gui.messagebox.showerror') as errors:
                    editor.open()
                    errors.assert_not_called()
                editor.search.set('gold')
                root.update()
                editor.fields.selection_set('gold')
                editor.selected()
                editor.value.set('400')
                editor.apply_selected()
                self.assertEqual(editor.changes, {'gold': 400})
                editor.pending_only.set(True)
                editor.refresh()
                self.assertEqual(editor.fields.get_children(), ('gold',))
                editor.undo()
                self.assertEqual(editor.changes, {})
                editor.pending_only.set(False)
                editor.refresh()
                editor.fields.selection_set('gold')
                editor.selected()
                editor.value.set('400')
                editor.apply_selected()
                editor.review()
                for child in root.winfo_children():
                    if isinstance(child, tk.Toplevel):
                        child.destroy()
                editor.apply_theme('Dark')
                destination = folder / 'EditedMainData00.dat'
                with patch('koei_editor.shared.verified_gui.filedialog.asksaveasfilename', return_value=str(destination)), \
                        patch('koei_editor.shared.verified_gui.messagebox.showerror') as errors:
                    editor.save_as()
                    errors.assert_not_called()
                reopened = parser.read_save(destination)
                self.assertEqual(parser.field_map(reopened)['gold'].value(reopened.payload), 400)
                self.assertEqual(source.read_bytes(), original)
                backup = next((folder / 'WarriorsEditorBackups').glob('*.dat'))
                restored = folder / 'RestoredMainData00.dat'
                with patch('koei_editor.shared.verified_gui.filedialog.askopenfilename', return_value=str(backup)), \
                        patch('koei_editor.shared.verified_gui.filedialog.asksaveasfilename', return_value=str(restored)), \
                        patch('koei_editor.shared.verified_gui.messagebox.showerror') as errors:
                    editor.restore()
                    errors.assert_not_called()
                self.assertEqual(restored.read_bytes(), original)
        finally:
            root.destroy()


class VitaFormatTests(unittest.TestCase):
    def setUp(self):
        self.raw = procedural_raw()
        self.document = parser.decode(self.raw)
        self.adapter = BoundScalarAdapter(parser.GAME_ID, '.dat', parser)

    def test_exact_plaintext_profile_and_noop_reject_foreign_corruption(self):
        self.assertEqual(parser.serialize(self.document, {}), self.raw)
        self.assertEqual(len(parser.BASE_FIELDS), 578)
        self.assertFalse(parser.FORMAT.sample_verified)
        self.assertFalse(parser.FORMAT.game_load_verified)
        for raw in (self.raw[:-1], self.raw + b'\0', bytearray(self.raw), b'bad!' + self.raw[4:]):
            with self.subTest(length=len(raw)), self.assertRaises(SaveError):
                parser.decode(raw)
        damaged = bytearray(self.raw)
        damaged[0x12345] ^= 1
        with self.assertRaisesRegex(SaveError, 'checksum'):
            parser.decode(bytes(damaged))
        with self.assertRaises(SaveError):
            parser.decode(self.raw, 'dw8xl_ps3')

    def test_surgical_resource_stats_aptitude_and_existing_rank_edits(self):
        mapping = parser.field_map(self.document)
        changes = {'gold': 900, 'officer_81_defense': 1100,
                   'officer_0_compatibility_0': 100, 'weapon_0_rank_0': 9}
        serialized = self.adapter.serialize(self.document, changes)
        saved = self.adapter.decode(serialized)
        allowed = {parser.PAYLOAD_SIZE}
        for key, value in changes.items():
            field = mapping[key]
            self.assertEqual(field.value(saved.payload), value)
            allowed.update(range(field.offset, field.offset + field.size))
        self.assertLessEqual({i for i, (a, b) in enumerate(zip(self.raw, serialized)) if a != b}, allowed)
        self.assertEqual(serialized[-1], sum(saved.payload) & 255)
        self.assertEqual(self.document.raw, self.raw)

    def test_unknown_empty_and_unusual_attributes_are_not_created(self):
        mapping = parser.field_map(self.document)
        self.assertIn('weapon_0_rank_0', mapping)
        for key in ('weapon_0_rank_1', 'weapon_0_rank_2', 'weapon_0_rank_5', 'weapon_1_rank_0'):
            self.assertNotIn(key, mapping)
            with self.assertRaises(SaveError):
                parser.stage(self.document, {}, key, 5)

    def test_unusual_opened_values_unstage_and_never_enter_max(self):
        raw = bytearray(self.raw)
        raw[0x105:0x109] = (20_000_000).to_bytes(4, 'little')
        raw[-1] = sum(raw[:-1]) & 255
        document = parser.decode(bytes(raw))
        changes = self.adapter.stage(document, {}, 'gold', 999)
        self.assertEqual(self.adapter.stage(document, changes, 'gold', 20_000_000), {})
        self.assertEqual(self.adapter.serialize(document, {'gold': 20_000_000}), document.raw)
        self.assertEqual(parser.maximums(document, changes), changes)
        self.assertEqual(parser.limit_values(document, changes, ['gold']), {})
        self.assertTrue(all(not field.maxable for field in parser.fields_for(document)))
        for bad in (True, -1, '99', 20_000_001):
            with self.subTest(value=bad), self.assertRaises(SaveError):
                self.adapter.stage(document, changes, 'gold', bad)

    def test_complete_pending_maps_and_foreign_snapshots_are_rejected(self):
        for changes in ({'bad': 3}, {'gold': True}, None, [], {'officer_0_compatibility_0': 30}):
            with self.subTest(changes=changes), self.assertRaises(SaveError):
                self.adapter.serialize(self.document, changes)
        for document in (replace(self.document, payload=b'x' * parser.PAYLOAD_SIZE),
                         replace(self.document, format=replace(parser.FORMAT, id='dw8xl_ps3')),
                         replace(self.document, source=None)):
            with self.assertRaises(SaveError):
                parser.serialize(document, {})

    def test_new_copy_backup_restore_and_actual_destination_readback(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            source, destination, restored = (root / name for name in ('copy.dat', 'edited.dat', 'restored.dat'))
            source.write_bytes(self.raw)
            document = self.adapter.read_save(source)
            saved = self.adapter.save_as(document, {'gold': 123}, destination)
            self.assertEqual(saved.raw, destination.read_bytes())
            self.assertEqual(parser.field_map(saved)['gold'].value(saved.payload), 123)
            self.assertEqual(source.read_bytes(), self.raw)
            snapshot = parser.backup(document)
            parser.restore(snapshot, restored)
            self.assertEqual(restored.read_bytes(), self.raw)
            with self.assertRaises(FileExistsError):
                self.adapter.save_as(document, {}, source)
            with self.assertRaises(FileExistsError):
                parser.restore(snapshot, restored)

    def test_source_races_and_damaged_restore_fail_before_writing(self):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            source = root / 'copy.dat'
            source.write_bytes(self.raw)
            document = parser.read_save(source)
            backup = parser.backup(document)
            backup.write_bytes(b'damaged')
            with self.assertRaises(SaveError):
                parser.restore(backup, root / 'restore.dat')
            self.assertFalse((root / 'restore.dat').exists())
            original_backup = parser.snapshot_backup

            def change_source(*args, **kwargs):
                result = original_backup(*args, **kwargs)
                source.write_bytes(b'changed')
                return result

            with patch.object(parser, 'snapshot_backup', side_effect=change_source):
                with self.assertRaises(SaveError):
                    parser.save_as(document, {'gold': 99}, root / 'race.dat')
            self.assertFalse((root / 'race.dat').exists())


@unittest.skipUnless(os.environ.get('DW8XL_VITA_REFERENCE_COPY'), 'Public native-format Vita reference not selected.')
class PublicReferenceTests(unittest.TestCase):
    def test_complete_reference_checksum_noop_and_representative_writer(self):
        raw = Path(os.environ['DW8XL_VITA_REFERENCE_COPY']).read_bytes()
        document = parser.decode(raw)
        self.assertEqual(parser.serialize(document, {}), raw)
        mapping = parser.field_map(document)
        for key in ('gold', 'gems', 'officer_0_attack', 'officer_0_compatibility_0'):
            field = mapping[key]
            value = 25 if '_compatibility_' in key else 1
            edited = parser.decode(parser.serialize(document, {key: value}))
            self.assertEqual(field.value(edited.payload), value)
            self.assertEqual(edited.raw[-1], sum(edited.payload) & 255)
